const reducer = (state, action) => {
  switch (action.type) {
    case "USERNAME":
      return { ...state, username: action.payload };
    case "EMAIL":
      return { ...state, email: action.payload };
    case "PWD":
      return { ...state, pwd: action.payload };
    case "CONFRIMPWD":
      return { ...state, confirmPwd: action.payload };
  }
};

export default reducer;
